select tasi.order_number, tna.event_title, tna.event_describe,tna.order_create_time, tna.order_end_time, tna.order_creator_id, tna.order_creator_name, tna.event_from, tna.happen_time,tna.recovery_time,tna.is_repeat,tna.close_code,tna.fault_system,tna.fault_type,tna.affected_business,tna.affected_feature,tna.affected_type,tna.affected_duration,tna.influence_area,tna.physics_env,tna.solution_details,tna.solution_conclusion,tna.system_id,tna.operate_duration,tna.solution_record,tna.fault_reason,tna.fault_by_upgrade,tna.fault_by_update,tna.influence_env,tna.is_invalid, tasi.fault_reason, tasi.solution_record,egmd.monitor_data from t_event_group_monitor_data as egmd left join t_alert_specific_info as tasi on egmd.order_number=tasi.order_number left join t_new_alert as tna on egmd.order_number=tna.order_number